 function scene(spec,options={}){
  const {practice=false,revealed=false,alternate=false}=options,step=Math.max(0,Math.min(3,Number(options.step)||0));
  const base=spec.bars.map(b=>({...b}));
  const tail=alternate?spec.other:spec.tail;
  const full=tail?base.concat(tail.map((c,i)=>{const o=i?tail[i-1]:base.at(-1).c;return bar(o,Math.max(o,c)+1,Math.min(o,c)-1,c);})):base;
  const counts=spec.counts?[...spec.counts,full.length]:[spec.cut,spec.cut,spec.cut,full.length];
  const count=practice&&!revealed?spec.cut:practice?full.length:counts[step];
  const forming=spec.mode==='ohlc'&&!practice&&step<3;
  const bars=forming?[[bar(100,100,100,100)],[bar(100,110,100,110)],[bar(100,110,95,95)]][step]:full.slice(0,count);
  return {bars,zone:spec.zone&&count>=(spec.zoneAt||1)?spec.zone:null,count,step,hidden:practice&&!revealed,forming};
 }
 function chart(bars,spec,width,zone,annotations=true){
  const g=geometry(bars,width),{x,y,plot:p}=g;
  let content='';
  for(let i=0;i<4;i++){const v=g.min+(g.max-g.min)*i/3;content+=`<line class="as-price-grid" x1="${p.left}" x2="${p.right}" y1="${y(v)}" y2="${y(v)}"/><text x="${p.left-6}" y="${y(v)+4}" text-anchor="end">${fmt(v)}</text>`;}
  if(zone){const high=Math.min(zone[1],g.max),low=Math.max(zone[0],g.min);if(high>=low)content+=`<rect class="as-price-zone" x="${p.left}" y="${y(high)}" width="${p.right-p.left}" height="${y(low)-y(high)}"/><text class="as-price-zone-label" x="${p.left+5}" y="${Math.max(p.top+13,y(high)+13)}">Область ${zone.map(fmt).join('–')}</text>`;}
  for(const v of [spec.level,spec.target].filter(Number.isFinite)){if(v>=g.min&&v<=g.max)content+=`<line class="as-price-level" x1="${p.left}" x2="${p.right}" y1="${y(v)}" y2="${y(v)}"/><text x="${p.right}" y="${y(v)-5}" text-anchor="end">${spec.target===v?'Ориентир':'Граница'} ${fmt(v)}</text>`;}
  bars.forEach((b,i)=>{const up=b.c>=b.o,bodyHeight=Math.max(1,Math.abs(y(b.o)-y(b.c)));content+=`<g class="as-price-candle ${up?'as-price-up':'as-price-down'}" data-index="${i}" data-o="${b.o}" data-h="${b.h}" data-l="${b.l}" data-c="${b.c}"><line x1="${x(i)}" x2="${x(i)}" y1="${y(b.h)}" y2="${y(b.l)}"/><rect x="${x(i)-g.candleWidth/2}" y="${Math.min(y(b.o),y(b.c))}" width="${g.candleWidth}" height="${bodyHeight}"/><title>Свеча${i+1}: O${b.o} H${b.h} L${b.l} C${b.c}</title></g>`;if(bars.length<=10||i%2===0)content+=`<text x="${x(i)}" y="${p.bottom+21}" text-anchor="middle">${i+1}</text>`;});
  if(spec.pivots)for(let i=1;i<bars.length-1;i++){const b=bars[i],high=b.h>bars[i-1].h&&b.h>bars[i+1].h,low=b.l<bars[i-1].l&&b.l<bars[i+1].l;if(high||low)content+=`<circle class="as-price-pivot" cx="${x(i)}" cy="${y(high?b.h:b.l)}" r="4"/>`;}
  if(spec.mode==='triangle'&&bars.length>=2)for(const prop of ['h','l'])content+=`<line class="as-price-level" x1="${x(0)}" y1="${y(bars[0][prop])}" x2="${x(Math.min(3,bars.length-1))}" y2="${y(bars[Math.min(3,bars.length-1)][prop])}"/>`;
  if(spec.mode==='ohlc'&&annotations){const b=bars[0],groups=new Map();for(const [label,v] of [['H',b.h],[spec.forming?'P':'C',b.c],['O',b.o],['L',b.l]]){groups.set(v,[...(groups.get(v)||[]),label]);}for(const [v,labels] of groups)content+=`<text x="${x(0)+30}" y="${y(v)+4}">${labels.join('/')} ${v}</text>`;}
  return `<svg class="as-price-svg" role="img" aria-label="${escape(spec.label)}" viewBox="0 0 ${width} ${g.height}" data-axis-min="${g.min}" data-axis-max="${g.max}"><title>${escape(spec.label)}</title>${content}<text x="${p.left}" y="16">Цена</text><text x="${p.right}" y="${g.height-2}" text-anchor="end">${spec.forming?'Текущий незавершённый интервал':'Закрытые интервалы'}</text></svg>`;
 }
 function extra(spec,s){
  const last=s.bars.at(-1),prices=`открытие ${fmt(last.o)}, максимум ${fmt(last.h)}, минимум ${fmt(last.l)}, закрытие ${fmt(last.c)}`;
  let text=s.forming?`Свеча не завершена: открытие${fmt(last.o)}, максимум${fmt(last.h)}, минимум${fmt(last.l)}; сейчас${fmt(last.c)}. Итоговое закрытие ещё неизвестно.`:`Последняя видимая свеча: ${prices}.`;
  if(spec.mode==='orderflow')return `<div class="as-diagram-paths"><p>Путь А: ${last.o} →${last.h} →${last.l} →${last.c}</p><p>Путь Б: ${last.o} →${last.l} →${last.h} →${last.c}</p><p>Лента, объёмы и стакан: <strong>данные отсутствуют</strong>.</p></div>`;
  if(spec.mode==='atr'){const tr=trueRanges(s.bars),values=atr(s.bars);text=`Истинные диапазоны (TR): ${tr.map(fmt).join(' · ')}. Их простое среднее за3 свечи (ATR): ${values.map(v=>v===null?'ещё нет3 свечей':fmt(v)).join(' · ')}.`;}
  if(spec.mode==='liquidity')text+=' Объёмы чужих заявок не предоставлены.';
  if(spec.mode==='session')text+=' Лимит150 − уже потеряно100 = остаток50; риск60 превышает остаток.';
  if(spec.mode==='fvg'&&s.bars.length>=3)text+=` Максимум первой${fmt(s.bars[0].h)}, минимум третьей${fmt(s.bars[2].l)}; область${spec.zone.map(fmt).join('–')}, середина${fmt((spec.zone[0]+spec.zone[1])/2)}.`;
  if(spec.mode==='three'&&s.bars.length>=3)text+=` Максимум третьей${s.bars[2].h} выше первого${s.bars[0].h}; закрытие третьей${s.bars[2].c} ниже первого${s.bars[0].c}.`;
  if(spec.mode==='patterns'&&s.bars.length>=2)text+=` Первое тело${Math.min(s.bars[0].o,s.bars[0].c)}–${Math.max(s.bars[0].o,s.bars[0].c)}, второе${Math.min(s.bars[1].o,s.bars[1].c)}–${Math.max(s.bars[1].o,s.bars[1].c)}; диапазоны${s.bars[0].l}–${s.bars[0].h} и${s.bars[1].l}–${s.bars[1].h}.`;
  return `<p class="as-price-readout">${escape(text)}</p>`;
 }
