 const previousFrames=new WeakMap();
 const lerp=(a,b,t)=>a+(b-a)*t;
 function morph(host,reduced){
  const previous=previousFrames.get(host);previous?.cancel?.();
  const nodes=typeof host.querySelectorAll==='function'?[...host.querySelectorAll('.as-price-candle')]:[];
  const frames=nodes.map(node=>{const wick=node.querySelector('line'),body=node.querySelector('rect');return{wick,body,values:[...['x1','x2','y1','y2'].map(k=>Number(wick.getAttribute(k))),...['x','y','width','height'].map(k=>Number(body.getAttribute(k)))]};});
  const write=(frame,values)=>{['x1','x2','y1','y2'].forEach((k,i)=>frame.wick.setAttribute(k,String(values[i])));['x','y','width','height'].forEach((k,i)=>frame.body.setAttribute(k,String(values[i+4])));};
  let request=null,stopped=false;
  const cancel=()=>{stopped=true;if(request!==null&&typeof window.cancelAnimationFrame==='function')window.cancelAnimationFrame(request);frames.forEach(f=>write(f,f.values));};
  previousFrames.set(host,{frames,cancel});
  if(!previous||reduced||!frames.length||typeof window.requestAnimationFrame!=='function')return cancel;
  const initial=frames.map((f,i)=>previous.frames[i]?.values||f.values);
  frames.forEach((f,i)=>write(f,initial[i]));
  let start=null;
  const tick=now=>{if(stopped)return;if(start===null)start=now;const t=Math.min(1,(now-start)/260),ease=1-(1-t)**3;frames.forEach((f,i)=>write(f,f.values.map((v,j)=>lerp(initial[i][j],v,ease))));if(t<1)request=window.requestAnimationFrame(tick);};
  request=window.requestAnimationFrame(tick);return cancel;
 }
